interface Expr { accept(visitor: ExprVisitor): number }

interface ExprVisitor {
  visitLiteral(l: Literal): number
  visitAdd(a: Add): number
}

class Literal implements Expr {
  constructor(public value: number) {}
  accept(v: ExprVisitor) { return v.visitLiteral(this) }
}

class Add implements Expr {
  constructor(public left: Expr, public right: Expr) {}
  accept(v: ExprVisitor) { return v.visitAdd(this) }
}

interface Operation {
  visitLiteral(l: Literal): number
  visitAdd(a: Add): number
}

class Literal implements Expr { accept(op: Operation) { return op.visitLiteral(this) } }
class Add implements Expr { accept(op: Operation) { return op.visitAdd(this) } }

// Many operation implementations exist across the codebase

/* Version A */
class Literal { value: number; evaluate() { return this.value } }
class Add { left: Expr; right: Expr; evaluate() { return this.left.evaluate() + this.right.evaluate() } }

/* Version B */
interface Operation { visitLiteral(l: Literal): number; visitAdd(a: Add): number }
class Literal { accept(op: Operation) { return op.visitLiteral(this) } }
class Add { accept(op: Operation) { return op.visitAdd(this) } }
